1	use crate::types::{ManaCost, ManaPool, ManaType, ManaSymbol};
2	#[cfg(test)]
3	use crate::types::Color;
4	
5	#[derive(Debug)]
6	pub enum ManaError {
7	    InsufficientMana,
8	}
9	
10	/// Check if a mana pool can pay a given cost.
11	pub fn can_pay(pool: &ManaPool, cost: &ManaCost) -> bool {
12	    // Clone pool to simulate payment.
13	    let mut sim = pool.clone();
14	    try_auto_pay(&mut sim, cost).is_ok()
15	}
16	
17	/// Automatically pay a mana cost from a pool.
18	/// Deducts the mana and returns Ok, or returns Err if insufficient.
19	///
20	/// Strategy: pay colored requirements first, then colorless requirements,
21	/// then generic from whatever remains.
22	pub fn auto_pay(pool: &mut ManaPool, cost: &ManaCost) -> Result<(), ManaError> {
23	    try_auto_pay(pool, cost)
24	}
25	
26	fn try_auto_pay(pool: &mut ManaPool, cost: &ManaCost) -> Result<(), ManaError> {
27	    // 1. Pay colored requirements.
28	    for sym in &cost.symbols {
29	        if let ManaSymbol::Colored(color) = sym {
30	            let mana_type = ManaType::from(*color);
31	            let available = pool.get(mana_type);
32	            if available == 0 {
33	                return Err(ManaError::InsufficientMana);
34	            }
35	            pool.mana.insert(mana_type, available - 1);
36	        }
37	    }
38	
39	    // 2. Pay specifically colorless requirements.
40	    let colorless_needed = cost.colorless_amount();
41	    if colorless_needed > 0 {
42	        let available = pool.get(ManaType::Colorless);
43	        if available < colorless_needed {
44	            return Err(ManaError::InsufficientMana);
45	        }
46	        pool.mana.insert(ManaType::Colorless, available - colorless_needed);
47	    }
48	
49	    // 3. Pay generic costs from whatever is left.
50	    let generic_needed = cost.generic_amount();
51	    if generic_needed > 0 {
52	        let total_remaining = pool.total();
53	        if total_remaining < generic_needed {
54	            return Err(ManaError::InsufficientMana);
55	        }
56	        let mut remaining = generic_needed;
57	        // Pay from colorless first, then from each color.
58	        let types = [
59	            ManaType::Colorless,
60	            ManaType::White, ManaType::Blue, ManaType::Black,
61	            ManaType::Red, ManaType::Green,
62	        ];
63	        for mt in types {
64	            if remaining == 0 { break; }
65	            let available = pool.get(mt);
66	            let to_use = available.min(remaining);
67	            if to_use > 0 {
68	                pool.mana.insert(mt, available - to_use);
69	                remaining -= to_use;
70	            }
71	        }
72	        if remaining > 0 {
73	            return Err(ManaError::InsufficientMana);
74	        }
75	    }
76	
77	    Ok(())
78	}
79	
80	#[cfg(test)]
81	mod tests {
82	    use super::*;
83	
84	    #[test]
85	    fn pay_simple_colored() {
86	        let mut pool = ManaPool::new();
87	        pool.add(ManaType::Green, 2);
88	
89	        let cost = ManaCost::new(vec![
90	            ManaSymbol::Colored(Color::Green),
91	            ManaSymbol::Colored(Color::Green),
92	        ]);
93	
94	        assert!(can_pay(&pool, &cost));
95	        assert!(auto_pay(&mut pool, &cost).is_ok());
96	        assert_eq!(pool.total(), 0);
97	    }
98	
99	    #[test]
100	    fn pay_generic_plus_colored() {
101	        let mut pool = ManaPool::new();
102	        pool.add(ManaType::Red, 2);
103	
104	        // {1}{R}
105	        let cost = ManaCost::new(vec![
106	            ManaSymbol::Generic(1),
107	            ManaSymbol::Colored(Color::Red),
108	        ]);
109	
110	        assert!(can_pay(&pool, &cost));
111	        assert!(auto_pay(&mut pool, &cost).is_ok());
112	        assert_eq!(pool.total(), 0);
113	    }
114	
115	    #[test]
116	    fn insufficient_mana() {
117	        let mut pool = ManaPool::new();
118	        pool.add(ManaType::Green, 1);
119	
120	        let cost = ManaCost::new(vec![
121	            ManaSymbol::Colored(Color::Green),
122	            ManaSymbol::Colored(Color::Green),
123	        ]);
124	
125	        assert!(!can_pay(&pool, &cost));
126	    }
127	
128	    #[test]
129	    fn pay_generic_with_mixed_pool() {
130	        let mut pool = ManaPool::new();
131	        pool.add(ManaType::Red, 1);
132	        pool.add(ManaType::Green, 2);
133	
134	        // {2}{G} — should pay G from green, then 2 generic from remaining green + red
135	        let cost = ManaCost::new(vec![
136	            ManaSymbol::Generic(2),
137	            ManaSymbol::Colored(Color::Green),
138	        ]);
139	
140	        assert!(can_pay(&pool, &cost));
141	        assert!(auto_pay(&mut pool, &cost).is_ok());
142	        assert_eq!(pool.total(), 0);
143	    }
144	
145	    #[test]
146	    fn wrong_color() {
147	        let pool_with_red = {
148	            let mut p = ManaPool::new();
149	            p.add(ManaType::Red, 2);
